Consider two bounded, possibly infinite sets $X^{+}, X^{-}\subset \mathbb{R}^d$ that are \emph{$\delta$-separated,} i.e., $\Vert x^{+}-x^{-}\Vert \geq \delta$ for all $x^{+}\in X^{+}$ and $x^{-}\in X^{-}$. Let $F: \mathbb{R}^d \to \mathbb{R}^{n}$ denote the function defined by a feedforward neural network. The fundamental problem of data separability asks if $F(X^{+})$ and $F(X^{-})$ are \emph{linearly separable}, i.e., if there exists a nonzero vector $a\in \mathbb{R}^n$ and constant $c$ such that
\[{a^{\intercal}F(x)+c}=\begin{cases}
> 0 &\textup{if }x\in X^{+}\\
< 0 &\textup{if }x\in X^{-}
\end{cases},\]
in which case the \emph{margin of separation} is $\inf\lbrace \vert a^{\intercal}y+c\vert/\Vert a\Vert :y\in F(X^{+}\cup X^{-})\rbrace$.

\[{a^{\intercal}F(x)+c}=\begin{cases}
> 0 &\textup{if }x\in X^{+}\\
< 0 &\textup{if }x\in X^{-}
\end{cases},\]

\label{def:complexity}
We say  two $\delta$-separated sets $X^{-}, X^{+}\subset R\mathbb{B}_{2}^{d}$ have \emph{$( \delta, \mu )$-mutual complexity} $N$, if $N=N^- + N^+$ is the minimum positive integer such that there exist two finite sets of \emph{centers} $C^+ = \{c_i^+\}_{i=1}^{N^+}\subset \mathbb{R}_2^d$ and $C^- = \{c_i^-\}_{i=1}^{N^-}\subset \mathbb{R}^d$, and two sets of constants $r_1^+, r_2^+, \ldots, r_{N^+}^+, r_1^-, r_2^-, \ldots, r_{N^-}^- \ge 0$ of \emph{radii} satisfying
\begin{enumerate}
\item $\bigcup_{i=1}^{N^+} X^+_i$ and $c_i^+\in\mathrm{conv} (X^+_i)$ where $X^+_i := X^+\cap \mathbb{B}_2^d(c_{i}^+, r_{i}^+)$,
\item $\bigcup_{j=1}^{N^-} X^-_j$ and $c_j^-\in\mathrm{conv} (X^-_j)$ where $X^-_j := X^-\cap \mathbb{B}_2^d(c_{j}^-, r_{j}^-)$,
\item $r_i^+ \le \mu^{-1}\mathrm{dist}^{2}\left(c_i^+, C^{-}\right)$,
\item $r_j^- \le \mu^{-1}\mathrm{dist}^{2}\left(c_j^-, C^{+}\right)$,
\item and $C^{+}, C^{-}$ are $\delta$-separated
\end{enumerate}
for every $i\in [N^+]$ and $j\in [N^-]$. As a special case where $\mu\to \infty$, the \emph{mutual complexity} of two finite sets $X^{+}$ and $X^{-}$ is the cardinality $N=\vert X^+\vert +\vert X^-\vert$.

\label{thm:main}
Fix any $\eta \in (0, 1)$ and $\delta$-separated $X^{+}, X^{-}\subset R\mathbb{B}_{2}^{d}$ with $d\geq 2$.
\begin{itemize}
	\item If $X^+$ and $X^-$ are finite, let $N:=\vert X^{+}\vert +\vert X^{-}\vert$, and let $\gamma: =\delta^{2}/8Rd$.
	\item Otherwise, let $N$ be the $(\delta, 64\delta^{-2}R^{3}d)$-mutual complexity of $X^+$ and $X^-$, and let $\gamma:= \delta^2/16Rd$.
\end{itemize}
For a one-layer RINN $\Phi(x):=\mathrm{ReLU}(Wx+b)$ with weights $W\in\mathbb{R}^{n\times d}$ and bias $b\sim \mathrm{Unif}\left([-\lambda, \lambda]^n\right)$, the sets $\Phi(X^{+}), \Phi (X^{-})\subset\mathbb{R}^{n}$ are linearly separable with probability at least $1-\eta$ by a margin at least $\mathcal{M}(\gamma,N)$ if width $n$ and maximal bias $\lambda$ satisfy either of the following, depending on how weights $W$ is sampled:
\begin{enumerate}
\item[(i)] $n\geq \frac{\log (N/\eta)}{p}$ and $\lambda\geq R$ if each row of the weight matrix $W_i\stackrel{iid}{\sim} \mathrm{Unif}(\mathbb{S}^{d-1})$,
\item[(ii)] $n\geq \frac{10\log (N/\eta)}{p}$ and $\lambda\geq 3R\sqrt{d}$ if weights $W\sim \mathrm{N}(0, I_{n\times d})$ are Gaussian,
\end{enumerate}
where we recall that $\mathrm{N}(0, I_{n\times d})$ means each entry is i.i.d. $\mathrm{N}(0, 1)$, and define
\begin{equation}\label{eq:p}
p:=\frac{R}{8(d-1)\lambda}\left(\frac{\delta^{2}}{8R^{2}}\right)^{d}\quad\text{and}\quad\mathcal{M}(\gamma,N):=\sqrt{\frac{4R(R+\gamma)}{N(1+2R/\gamma)^{2N}-N}}.
\end{equation}

\begin{equation}\label{eq:p}
p:=\frac{R}{8(d-1)\lambda}\left(\frac{\delta^{2}}{8R^{2}}\right)^{d}\quad\text{and}\quad\mathcal{M}(\gamma,N):=\sqrt{\frac{4R(R+\gamma)}{N(1+2R/\gamma)^{2N}-N}}.
\end{equation}

To state it, we define the \emph{Gaussian width} $w(T)$ of a subset $T\subset \mathbb{R}^n$ (\cite[Definition~7.5.1]{Ver18}) as
\begin{equation}\label{eq:w}
 w(T) := \mathbb{E}\left[\sup_{x\in T} g^{\intercal}x\right] \text{ where } g\sim \mathrm{N}(0, I_{n}).
\end{equation}

\begin{equation}\label{eq:w}
 w(T) := \mathbb{E}\left[\sup_{x\in T} g^{\intercal}x\right] \text{ where } g\sim \mathrm{N}(0, I_{n}).
\end{equation}

\label{thm:main in k}
There exists a constant $C = C(\delta, R)>0$ such that the following holds. Fix any $\eta \in (0, 1)$ and $\delta$-separated $X^{+}, X^{-}\subset R\mathbb{B}_{2}^{d}$ with $d\geq 2$.


\begin{itemize}
	\item If $X^+$ and $X^-$ are finite, let $N:=\vert X^{+}\vert +\vert X^{-}\vert$, and let $\gamma: =\delta^{2}/18R\sqrt{k}$.
	\item Otherwise, let $N$ be the $(\delta, 144\delta^{-2}R^{3}\sqrt{k})$-mutual complexity of $X^+$ and $X^-$, and let $\gamma:= \delta^{2}/36R\sqrt{k}$, where in both cases we let
\begin{equation}\label{eq:k}
 k := C\left(\frac{32R}{\delta^2}\right)^2\left(w\left((X^+-X^-)\cup X^+\cup X^-\right)^2+R^2\right).
\end{equation}
\end{itemize}
For a one-layer RINN $\Phi(x):=\mathrm{ReLU}(Wx+b)$ with standard Gaussian weights $W\sim \mathrm{N}(0, I_{n\times d})$ and bias $b\sim \mathrm{Unif}\left([-\lambda, \lambda]^n\right)$, the sets $\Phi(X^{+}), \Phi (X^{-})\subset\mathbb{R}^{n}$ are linearly separable with probability at least $1-\eta$ by a margin at least $\mathcal{M}(\gamma,N)$ defined in \eqref{eq:p}, provided maximal bias $\lambda \geq 9R\sqrt{k}/8$ and width \begin{equation}\label{eq:q}
n \geq \frac{\log (N/\eta)}{q}, \quad \text{where}\quad  q :=\frac{R}{4\lambda \sqrt{k}}\left(\frac{2\delta^2}{81R^2}\right)^k.
\end{equation}

\begin{equation}\label{eq:k}
 k := C\left(\frac{32R}{\delta^2}\right)^2\left(w\left((X^+-X^-)\cup X^+\cup X^-\right)^2+R^2\right).
\end{equation}

\begin{equation}\label{eq:q}
n \geq \frac{\log (N/\eta)}{q}, \quad \text{where}\quad  q :=\frac{R}{4\lambda \sqrt{k}}\left(\frac{2\delta^2}{81R^2}\right)^k.
\end{equation}

