\caption{Construct a one-layer NN separating two finite sets with a margin}
\label{alg:det_onelayer}
\begin{algorithmic}[1]
\Require Two $\delta$-separated finite sets $X^{+}, X^{-}\subset R\mathbb{B}_{2}^{d}$ and $\gamma \in [0, \max(\delta^2/8Rd, \delta^2/18R\sqrt{k})]$.
\Ensure A one-layer neural network $\Phi$ such that $\Phi(X^{+})$ and $\Phi(X^{-})$ are linearly separable.

\For{$i = 1,2,\ldots,N$}
\State $x_i \gets x$ where $x$ has the $i$-th largest norm in $X^+ \cup X^-$.
\EndFor
\For{$i = 1,2,\ldots,N$}

    \State Find $w\in \mathbb{S}^{d-1}$ and $b\in \mathbb{R}$ such that $w^{\intercal}x_i +b\geq \gamma$ and $w^{\intercal}x_j+b\leq -\gamma$ for all $j > i$ and $\sigma(x_i) \neq \sigma(x_j)$. If no such $j$ exists, ask $w^{\intercal}x_i +b\geq \gamma$ and $w^{\intercal}x +b \leq 0$ for some $x\in R\mathbb{B}_2^d$.

    \State $w_i \gets w$, $b_i \gets b$, $h_i \gets$ the function $w^{\intercal}_ix + b_i$ 

\EndFor
\State $W \gets$ the matrix with row vectors $w_i^{\intercal}$
\State $b \gets$ the vector with components $b_i$
\State \Return the function $\Phi(x)=\mathrm{ReLU}(Wx + b)$
\end{algorithmic}

\label{thm:prob}
For any two $\delta$-separated finite sets $X^{+}, X^{-}\subset R\mathbb{B}_{2}^{d}$, define $x_i$ and $\sigma$ as in \cref{alg:det_onelayer} and \eqref{eq:sigma}. Consider the random affine function $h(z)=v^{\intercal}z+t$ where $t\in \mathbb{R},v\in \mathbb{R}^d$ are independent random variables with $t\sim\mathrm{Unif}\left([-\lambda, \lambda]\right)$ and the distribution of $v$ is specified below. For any $\gamma>0$, let
\[ B_{i}:=\left\lbrace h(x_{i})\geq \gamma \right\rbrace\cap \bigcap_{j:j>i, \sigma(x_i) \neq\sigma(x_j)  }\left\lbrace h(x_{j})\leq -\gamma \right\rbrace\]
for each $i\in [N]$. Recall $p$ from \eqref{eq:p} and $q$ from \eqref{eq:q}. Then, there exists some $C=C(\delta, R)>0$ in the definition \eqref{eq:k} of $k$ such that the following hold:
\begin{enumerate}
    \item[(i)] For all $i$ and $\gamma \leq {\delta^{2}}/{8Rd}$, $\mathbb{P} (B_{i})\geq p$ if $v\sim\mathrm{Unif} \left(\mathbb{S}^{d-1}\right)$ and $\lambda\geq R$.
    \item[(ii)] For all $i$ and $\gamma \leq {\delta^{2}}/{8Rd}$, $\mathbb{P} (B_{i})\geq p/10$ if $v\sim \mathrm{N}(0, I_{d})$ and $\lambda\geq 3R\sqrt{d}$.
    \item[(iii)] For all $i$ and $\gamma \leq {\delta^{2}}/{18R\sqrt{k}}$, $\mathbb{P} (B_{i})\geq q$ if $v\sim \mathrm{N}(0, I_{d})$ and $\lambda\geq 9R\sqrt{k}/8$.
\end{enumerate}

Here, $v\sim \mathrm{Unif}(\mathbb{S}^{d-1})$. The idea is to condition on $v$ being close to $x_i/\Vert x_i\Vert$ and find which $t$ makes $h(z)=v^{\intercal}z+t$ satisfy $B_i$. Note, for any $x_{j} \in X^{+}\cup X^{-}$ with $j >i$ and $\sigma(x_i)\neq \sigma(x_j)$, we know $\Vert x_j\Vert \leq \Vert x_{i}\Vert$ by our ordering and $ \Vert x-x_{i}\Vert\geq \delta$ by $\delta$-separation. First, for any $j$ as in the definition of $B_i$, we show $x_i^{\intercal}x_j\leq \Vert x_i\Vert ^2 - \delta^2/2$ as follows:
\[
\delta^{2} \le (x_{i}-x_{j})^{\intercal}(x_{i}-x_{j}) 
= \Vert x_{i}\Vert ^{2}+\Vert x_{j}\Vert^{2}-2x_{i}^{\intercal}x_{j}
\leq 2\Vert x_i\Vert ^{2}-2x_{i}^{\intercal}x_{j}.
\]

Now, define $\widehat{x}_{i}=x_{i}/\Vert x_{i}\Vert$. For every $v\in \mathbb{S}^{d-1}$, we note $\widehat{x}_i^{\intercal}x_i=\Vert x_i\Vert\leq R$ and bound $\left(v-\widehat{x}_{i}\right)^{\intercal}x_{i}\geq-\|v-\widehat{x}_{i}\|\cdot \|x_{i}\|$ by Cauchy-Schwarz to obtain
\begin{equation}\label{eq:vxi}
v^{\intercal}x_{i} = \widehat{x}_{i}^{\intercal}x_{i} + \left(v-\widehat{x}_{i}\right)^{\intercal}x_{i} \geq \Vert x_{i}\Vert - \Vert v-\widehat{x}_{i}\Vert \cdot \Vert x_{i}\Vert\geq \Vert x_{i}\Vert - R\Vert v-\widehat{x}_{i}\Vert.
\end{equation}

Now, for any $j$ as in the definition of $B_i$, write $v^{\intercal}x_{j} = \widehat{x}_{i}^{\intercal}x_{j} + \left(v-\widehat{x}_{i}\right)^{\intercal}x_{j}$. We had $x_i^{\intercal}x_j\leq \Vert x_i\Vert ^2 - \delta^2/2$, so $\widehat{x}_i^{\intercal}x_j\leq \Vert x_i\Vert - \delta^2/2\Vert x_i\Vert$. Since $\Vert x_j\Vert \leq \Vert x_i\Vert\leq R$ and $\left(v-\widehat{x}_{i}\right)^{\intercal}x_{j}\leq \Vert v-\widehat{x}_{i}\Vert\cdot \Vert x_{j}\Vert$ by Cauchy-Schwarz, we obtain
\begin{equation}\label{eq:vxj}
v^{\intercal}x_{j}  \leq \Vert x_{i}\Vert -\frac{\delta^{2}}{2\Vert x_{i}\Vert} + \Vert v-\widehat{x}_{i}\Vert\cdot \Vert x_{j}\Vert \leq \Vert x_{i}\Vert -\frac{\delta^{2}}{2R} + R\Vert v-\widehat{x}_{i}\Vert.
\end{equation}

Recall that $h(z)=v^{\intercal}z+t$ and $B_i$ occurs if and only if $v^{\intercal}x_i+t\geq \gamma$ and $v^{\intercal}x_j+t\leq-\gamma$ for all $j$ where $j>i$ and $\sigma (x_j)\neq\sigma (x_i)$. This is equivalent to $t\geq \gamma-v^{\intercal}x_i$ and $t\leq -\gamma-v^{\intercal}x_j$ for all such $j$. We bound $\vert v^{\intercal}x_i\vert \leq \Vert v\Vert \cdot\Vert x_i\Vert \leq R$ and similarly $\vert v^{\intercal}x_{j}\vert \leq R$. Hence, for a fixed $v$, $B_i$ occurs if
\[ t\in I:=\left[\gamma - v^{\intercal}x_i, \  -\gamma - \max_{j:j>i, \sigma(x_j)\neq\sigma(x_i)}v^{\intercal}x_j\right] \subset [-R, R]\subset [-\lambda, \lambda] \]
as $\lambda\geq R$. Hence, we bound $\mathbb{P}(B_i\mid v)$ below from by the length of $I$ over $2\lambda$, i.e.
\[ \mathbb{P}_{t}\left(B_{i}\mid v\right) \geq \frac{1}{2\lambda}\left(v^{\intercal}x_{i}-\max_{j:j>i, \sigma(x_j)\neq \sigma(x_i)}( v^{\intercal}x_{j}) -2\gamma\right)\geq \frac{1}{2\lambda}\left(\frac{\delta^{2}}{2 R}-2R\Vert v-\widehat{x}_{i}\Vert -2\gamma\right)\]
where the second inequality follows from \eqref{eq:vxi} and \eqref{eq:vxj}. Let $r:=\left({\delta^{2}}/{4R^{2}}\right)\left(1-{1}/{d}\right)$. Now, $r\in [0,2]$ as $\delta \leq 2R$. As $v\sim \mathrm{Unif}(\mathbb{S}^{d-1})$, applying \cref{lem:geo lm}(1) gives
\[
\mathbb{P}(B_{i}) \geq \mathbb{P}\left(B_{i}\mid \Vert v-\widehat{x}_{i}\Vert \leq r\right)\cdot \mathbb{P}_{t}\left(\Vert v-\widehat{x}_{i}\Vert \leq r\right)
\geq \frac{1}{2\lambda}\left(\frac{\delta^{2}}{2R}-2Rr-2\gamma\right)\left(\frac{1}{2}\right)\left(\frac{r}{2}\right)^{d-1}.
\]
Plug in $r$ and bound $\gamma \leq \delta^{2}/8Rd$ to obtain
\begin{align*}
\mathbb{P}(B_{i}) & \geq \frac{1}{4\lambda}\left[\frac{\delta^{2}}{2R}-2R\cdot \frac{\delta^{2}}{4R^{2}}\left(1-\frac{1}{d}\right)-2\cdot \frac{\delta^{2}}{8Rd} \right]\left[\frac{\delta^{2}}{8R^{2}}\left(1-\frac{1}{d}\right)\right]^{d-1}
\\ &  = \frac{1}{4\lambda}\left(\frac{\delta^{2}}{4Rd}\right)\left(\frac{\delta^{2}}{8R^{2}}\right)^{d-1}\left(1-\frac{1}{d}\right)^{d-1} 
\\ & \geq \frac{R}{8(d-1)\lambda}\left(\frac{\delta^{2}}{8R^{2}}\right)^{d}
\\ & = p
\end{align*}
where the second inequality follows from the fact that $(1-1/d)^d$ is increasing in $d$ for $d\geq 2$, so it is at least its value $1/4$ at $d=2$. This establishes Case (i).

\begin{equation}\label{eq:vxi}
v^{\intercal}x_{i} = \widehat{x}_{i}^{\intercal}x_{i} + \left(v-\widehat{x}_{i}\right)^{\intercal}x_{i} \geq \Vert x_{i}\Vert - \Vert v-\widehat{x}_{i}\Vert \cdot \Vert x_{i}\Vert\geq \Vert x_{i}\Vert - R\Vert v-\widehat{x}_{i}\Vert.
\end{equation}

\begin{equation}\label{eq:vxj}
v^{\intercal}x_{j}  \leq \Vert x_{i}\Vert -\frac{\delta^{2}}{2\Vert x_{i}\Vert} + \Vert v-\widehat{x}_{i}\Vert\cdot \Vert x_{j}\Vert \leq \Vert x_{i}\Vert -\frac{\delta^{2}}{2R} + R\Vert v-\widehat{x}_{i}\Vert.
\end{equation}

\begin{align*}
\mathbb{P}(B_{i}) & \geq \frac{1}{4\lambda}\left[\frac{\delta^{2}}{2R}-2R\cdot \frac{\delta^{2}}{4R^{2}}\left(1-\frac{1}{d}\right)-2\cdot \frac{\delta^{2}}{8Rd} \right]\left[\frac{\delta^{2}}{8R^{2}}\left(1-\frac{1}{d}\right)\right]^{d-1}
\\ &  = \frac{1}{4\lambda}\left(\frac{\delta^{2}}{4Rd}\right)\left(\frac{\delta^{2}}{8R^{2}}\right)^{d-1}\left(1-\frac{1}{d}\right)^{d-1} 
\\ & \geq \frac{R}{8(d-1)\lambda}\left(\frac{\delta^{2}}{8R^{2}}\right)^{d}
\\ & = p
\end{align*}

Here, $v\sim \mathrm{N}(0, I_{d})$. By \cref{lem:prob lm}(1), we can change variables to $\rho = \Vert v\Vert$ with $\rho^2\sim \chi^2_d$ and $\widehat{v}=v/\rho\sim \mathrm{Unif}(\mathbb{S}^{d-1})$, which are independent. For any $1\leq \rho\leq 3\sqrt{d}$, we compute
\begin{align*}
\mathbb{P}(B_i\mid \rho) & = \mathbb{P}\left(\widehat{v}^{\intercal}x+t/\rho \geq \gamma/\rho \ \forall \ x\in X^+ \text{ and } \widehat{v}^{\intercal}x+t/\rho \leq -\gamma/\rho \ \forall \ x\in X^-\right)
\\ & \geq \mathbb{P}\left(\widehat{v}^{\intercal}x+t/\rho \geq \gamma \ \forall \ x\in X^+ \text{ and } \widehat{v}^{\intercal}x+t/\rho \leq -\gamma \ \forall \ x\in X^-\right)
\\ & \geq \mathbb{P}\left(\widehat{v}^{\intercal}x+t/\rho\text{ satisfies event }B_i\right).
\end{align*}
Now, $\widehat{v}\sim\mathrm{Unif}(\mathbb{S}^{d-1})$ and, for a fixed $\rho$, $t/\rho \sim \mathrm{Unif}([-\lambda/\rho, \lambda/\rho]$. Since $\rho\leq 3\sqrt{d}$ and $\lambda\geq 3\sqrt{d}R$, $\lambda/\rho\geq R$. Hence, Case (i) applies to show 
\[ \mathbb{P}(B_i\mid \rho) \geq \mathbb{P}\left(\widehat{v}^{\intercal}x+t/\rho\text{ satisfies event }B_i\right) \geq p.\]
This holds for every $\rho$ where $1\leq\rho\leq 3\sqrt{d}$. By conditioning on it, we obtain

\begin{align*}
	\mathbb{P}(B_i) & \geq \mathbb{P}\left(B_i\mid 1\leq \rho\leq 3\sqrt{d}\right)\cdot \mathbb{P}\left(1\leq \rho\leq 3\sqrt{d}\right)
	\\ & \geq \frac{1}{10}\inf\left\lbrace \mathbb{P}(B_i\mid\rho) : {1\leq \rho\leq 3\sqrt{d}}\right\rbrace 
	\\ & \geq \frac{p}{10}
\end{align*}
where $ \mathbb{P}(1\leq \rho\leq 3\sqrt{d})\geq 1/10$ by \cref{prop:chi}, showing Case (ii).

