\\ & = \frac{\sqrt{k}}{\lambda}\left(\frac{(\delta -\theta)^2}{4(\ell+\theta)} -\frac{2\ell\theta}{\ell-\theta}  - (\ell+\theta)\Vert u-\widehat{y}_{i}\Vert - \frac{\gamma}{\sqrt{k}}\right) 
\\ & = \frac{\sqrt{k}}{\lambda}\left(\frac{(\delta -\theta)^2}{4(\ell+\theta)} -\frac{2 (\delta^2/32R)}{1-\theta/\ell}  - (\ell+\theta)\Vert u-\widehat{y}_{i}\Vert - \frac{\gamma}{\sqrt{k}}\right) 
\end{align*}

\begin{align*}
\mathbb{P}(B_{i}\mid E, u) & \geq \frac{\sqrt{k}}{\lambda}\left(\frac{(15\delta/16)^2}{4(R+\delta/16)} -\frac{2 (\delta^2/32R)}{1-(\delta/16)/(\delta/2)}  - (R+\delta/16)\Vert u-\widehat{y}_{i}\Vert - \frac{\gamma}{\sqrt{k}}\right)
\\ & \geq \frac{\sqrt{k}}{\lambda}\left(\frac{(15\delta/16)^2}{4(R+R/8)} -\frac{2(\delta^2/32R)}{1-(\delta/16)/(\delta/2)}  - (R+R/8)\Vert u-\widehat{y}_{i}\Vert - \frac{\gamma}{\sqrt{k}}\right) 
\\ & = \frac{\sqrt{k}}{\lambda}\left(\frac{111}{896}\cdot\frac{\delta^2}{R} - (9R/8)\cdot\Vert u-\widehat{y}_{i}\Vert - \frac{\gamma}{\sqrt{k}}\right) 
\\ & \geq \frac{\sqrt{k}}{\lambda}\left(\frac{\delta^2}{18R} - (9R/8)\cdot\Vert u-\widehat{y}_{i}\Vert\right) 
\end{align*}

\begin{align*}
\mathbb{P}(B_{i}\mid E) & \geq\mathbb{P}\left(B_{i}\mid E, \Vert u-\widehat{y}_{i}\Vert \leq r\right)\cdot \mathbb{P}_{t}\left(\Vert u-\widehat{y}_{i}\Vert \leq r\right)
\\ & \geq \frac{\sqrt{k}}{\lambda}\left(\frac{\delta^2}{18R} - \frac{9Rr}{8}\right) \cdot \left(\frac{1}{2}\right)\left(\frac{r}{2}\right)^{k-1}
\\ & = \frac{\sqrt{k}}{\lambda}\left(\frac{\delta^2}{18R} - \frac{9R}{8}\cdot \frac{4\delta^2}{81R^2}\left(1-\frac{1}{k}\right)\right) \left(\frac{1}{2}\right)\left(\frac{2\delta^2}{81R^2}\left(1-\frac{1}{k}\right)\right)^{k-1}
\\ & = \frac{\sqrt{k}}{2\lambda}\left(\frac{\delta^2}{18Rk}\right) \left(\frac{2\delta^2}{81R^2}\right)^{k-1}\left(1-\frac{1}{k}\right)^{k-1}
\\ & \geq \frac{\sqrt{k}}{2\lambda}\left(\frac{9R}{4k}\right) \left(\frac{2\delta^2}{81R^2}\right)^{k}\left(1-\frac{1}{k}\right)^{-1}\left(\frac{1}{4}\right)
\\ & \geq  \frac{9}{32}\left(\frac{R}{\lambda\sqrt{k}}\right) \left(\frac{2\delta^2}{81R^2}\right)^{k}
\end{align*}

\caption{Separate the image of the sets under the output of \cref{alg:det_onelayer}}
\label{alg:weights}
\begin{algorithmic}[1]
\Require Two $\delta$-separated finite sets $X^{+}, X^{-}\subset R\mathbb{B}_2^d$ and parameter $\gamma$ satisfying the input conditions of \cref{alg:det_onelayer}, and the output $\Phi$ of \cref{alg:det_onelayer} on $X^{+}, X^{-}$, and $\gamma$.
\Ensure A hyperplane $H\subset \mathbb{R}^N$ separating $\Phi(X^+)$ and $\Phi(X^-)$ with margin at least $\sqrt{N}\mathcal{M}(\gamma, N)$.
\For{$i = N,N-1,\ldots,1$}
    \State $a_i\gets\sigma(x_i)\left(1+\left\vert\sum_{j=i+1}^Na_j(\Phi(x_i))_j\right\vert\right)/\gamma$.
\EndFor
\State \Return the hyperplane $H(z)=a^{\intercal}z$ where $a=(a_i)_i\in\mathbb{R}^N$.
\end{algorithmic}

By definition of $h_j$ in \cref{alg:det_onelayer} and event $B_j$, we have that 
\begin{equation}\label{eq:hj}
h_{j}(x_{i})=\begin{cases}
\leq -\gamma & \textup{if $j<i$ and $\sigma(x_j) \neq \sigma(x_i) $}\\
\geq \gamma  & \textup{if $j=i$}\\
* & \textup{otherwise}
\end{cases}
\end{equation}
where $*$ denotes unknown reals. Hence, after activation,
\begin{equation}\label{eq:phij}
(\Phi(x_i))_j=\mathrm{ReLU}(h_{j}(x_{i}))=\begin{cases}
0  & \textup{if $j<i$ and $\sigma(x_j) \neq \sigma(x_i) $}\\
\geq \gamma  & \textup{if $j=i$}\\
\geq 0 & \textup{otherwise}
\end{cases}.
\end{equation}

As in \cref{alg:weights}, we choose the weight vector $a\in\mathbb{R}^N$ by picking $a_{i}$ recursively for $i=N, N-1, \dots , 1$ as follows:
\begin{equation}\label{eq:weight_vec_choice}
    a_{i}=\frac{\sigma(x_i)}{\gamma }\left(1+\left\vert\sum_{j=i+1}^{N}a_{j}(\Phi(x_{i}))_{j}\right\vert\right).
\end{equation}
Note that $a_i$ has same sign as $\sigma(x_i)$. Let $H(z) = a^{\intercal}z$ be an affine function associated with the hyperplane $\{z : H(z) = 0\}$. We first claim and prove that $H$ separates the points of $\Phi(X^{+})$ and $\Phi(X^{-})$, and then derive the lower bound on the margin of separation.

\begin{claim}\label{claim:H sep}
$H$ separates $\Phi(X^{+})$ and $\Phi(X^{-})$ with margin at least $1/\Vert a\Vert$.
\end{claim}
\begin{proof}[Proof of \cref{claim:H sep}]
It suffices to show $H (\Phi(x_{i}))\geq 1$ if $x_{i}\in X^{+}$ and $H (\Phi(x_{i}))\leq -1$  if $x_{i}\in X^{-}$. For every $1 \le i \le N$, we have
\begin{align}\label{eq:4terms}
\sigma(x_i)  H(\Phi(x_{i})) & = \sigma(x_i) \sum_{j=1}^{N}a_{j}(\Phi(x_{i}))_{j} \nonumber
\\ & = \sigma(x_i) \sum_{j<i, \sigma(x_j) =\sigma(x_i) }a_{j}(\Phi(x_{i}))_{j} + \sigma(x_i) \sum_{j<i, \sigma(x_j) \neq \sigma(x_i) }a_{j}(\Phi(x_{i}))_{j}\nonumber
\\ & \qquad + \sigma(x_i) a_{i}(\Phi(x_{i}))_{i} + \sigma(x_i) \sum_{j>i}a_{j}(\Phi(x_{i}))_{j}
\end{align}
where the second equality is obtained by splitting the summation into four groups depending on whether $j < i$, $j = i,$ or $j > i$, and depending on whether $\sigma(x_j) = \sigma(x_i)$. We consider each quantity.

For each term in the first quantity, $a_j$ has the same sign as $\sigma(x_j)=\sigma(x_i)$, so
\begin{equation}\label{eq:first_term}
    \sigma(x_i) \sum_{j<i, \sigma(x_j) =\sigma(x_i) }a_{j}(\Phi(x_{i}))_{j} = \sum_{j<i, \sigma(x_j) =\sigma(x_i) }\sigma(x_j)a_{j}(\Phi(x_{i}))_{j} \ge 0.
\end{equation}
For each term in the first quantity, $(\Phi(x_i))_j = 0$ if $j<i$ and $\sigma(x_j) \neq \sigma(x_i)$, so
\begin{equation}\label{eq:second_term}
    \sigma(x_i) \sum_{j<i, \sigma(x_j) \neq \sigma(x_i) }a_{j}(\Phi(x_{i}))_{j} = 0.
\end{equation}
For the third quantity, from \eqref{eq:phij} we have $(\Phi(x_{i}))_{i} \ge \gamma$, and from \eqref{eq:weight_vec_choice}, so
\begin{equation}\label{eq:third_term}
    \sigma(x_i) a_{i}(\Phi(x_{i}))_{i} \ge \frac{\sigma(x_i) ^{2}}{\gamma}\left(1+\left|\sum_{j>i}a_{j}(\Phi(x_{i}))_{j}\right|\right)\gamma = 1+\left|\sum_{j>i}a_{j}(\Phi(x_{i}))_{j}\right|.
\end{equation}
Plugging \eqref{eq:first_term}, \eqref{eq:second_term}, and \eqref{eq:third_term} into \eqref{eq:4terms} gives the first inequality below
\[
\sigma(x_i)  H(\Phi(x_{i}))  \geq 0 + 0 + 1+\left|\sum_{j>i}a_{j}(\Phi(x_{i}))_{j}\right| + \sigma(x_i) \sum_{j>i}a_{j}(\Phi(x_{i}))_{j}
 \geq 1,
\]
and the second inequality follows by the triangle inequality. This shows $H (\Phi(x_{i}))\geq 1$ if $x_{i}\in X^{+}$ and $H (\Phi(x_{i}))\leq -1$  if $x_{i}\in X^{-}$, so the margin is at least $1/\Vert a\Vert$.
\end{proof}

We now further lower bound the margin of separation $1/\Vert a\Vert$.

\begin{claim}\label{claim:margin bd}
For $a$ defined in \eqref{eq:weight_vec_choice} and $\mathcal{M}$ defined in \eqref{eq:p}, $1/\Vert a\Vert \geq \sqrt{N}\mathcal{M}(\gamma, N)$.
\end{claim}
\begin{proof}[Proof of \cref{claim:margin bd}]
We first show that $(\Phi(x_i))_{j}\leq 2R$ for all $j>i$ such that $\sigma(x_i)\neq \sigma(x_j)$. We start by showing  for all $i$, $h_{i}(x)=0$ for some $x\in R\mathbb{B}_{2}^{d}$. This just follows from the observations that each of our hyperplanes $\lbrace h_i=0\rbrace$ intersects $R\mathbb{B}_2^d$ by assumption. More rigorously, consider the two cases on line 5 of \cref{alg:det_onelayer}, either way we have $h_{i}(x_{i})>0$ and $h_{i}(x_{j})\leq 0$ for some $x_{i}, x_{j}\in R\mathbb{B}_{2}^{d}$. Then, by the intermediate value theorem, there is some $x$ on the segment $x_{i}x_{j}$ such that $h_{i}(x)=0$. Since $R\mathbb{B}_{2}^{d}$ is convex, $x\in R\mathbb{B}^{d}_{2}$. Then, for every $y\in R\mathbb{B}_{2}^{d}$, since $w_{i}\in \mathbb{S}^{d-1}$ we have
\begin{equation}\label{eq:hiy}
\vert h_{i}(y)\vert \leq \vert h_{i}(x)\vert + \vert h_{i}(y)-h_{i}(x)\vert 
 \leq \vert w_{i}^{\intercal}(y-x)\vert 
\leq \Vert w_{i}\Vert \cdot \Vert y-x\Vert
\le 2R.
\end{equation}
Here, we used the triangle inequality to obtain the first inequality, used that $h_i(x) = 0$ to get the second inequality, applied the Cauchy-Schwarz Inequality in the third inequality, and used the fact that $x,y \in R\mathbb{B}_2^d$ to get the final inequality. By using the upper bound in \eqref{eq:hiy}, 
\[
\vert a_{i}\vert = \frac{1}{\gamma }\left( 1+\left|\sum_{j=i+1}^{N}a_{j}(\Phi(x_{i}))_{j}\right|\right)
\leq \frac{1}{\gamma} \left(1+2R \sum_{j=i+1}^{N}\vert a_{j}\vert\right),
\]
where we used the triangle inequality to obtain the last inequality. Thus, $\vert a_{i}\vert \leq \tilde{a}_{i}$ where $\tilde{a}_{i}$ is a sequence defined recursively by $\tilde{a}_{N}= 1/\gamma = \vert a_{N}\vert$ and 
\[
    \tilde{a}_{i} = \frac{1}{\gamma}\left(1 + 2R \sum_{j=i+1}^N \tilde{a}_j\right).
\]
We compute $\tilde{a}_{i}$ explicitly. Taking the successive differences
\[
    \tilde{a}_{i-1}-\tilde{a}_{i} = \frac{1}{\gamma}\left(1 + 2R \sum_{j=i}^N \tilde{a}_j\right) - \frac{1}{\gamma}\left(1 + 2R \sum_{j=i+1}^N \tilde{a}_j\right) = \frac{2R\tilde{a}_{i}}{\gamma},
\]




 and using the fact that $\tilde{a}_{N}= 1/\gamma$, we get
\[
    \tilde{a}_{i} = \frac{1}{\gamma}\left(1+\frac{2R}{\gamma}\right)^{N-i}.
\]
Hence,
\[
\Vert a\Vert ^{2} \leq \sum_{i=1}^{N}\frac{1}{\gamma^{2}}\left(1+\frac{2R}{\gamma}\right)^{2(N-i)} = \frac{1}{\gamma^{2}} \cdot \frac{(1+2R/\gamma)^{2N}-1}{(1+2R/\gamma )^{2}-1} = \frac{(1+2R/\gamma)^{2N}-1}{4R(R+\gamma)},
\]
which gives the desired bound by rearranging.
\end{proof}
Therefore, \cref{claim:H sep} and \cref{claim:margin bd} together implies that $H$ separates $\Phi(X^+)$ and $\Phi(X^-)$ by a margin at least $\sqrt{N}\mathcal{M}(\gamma, N)$, as desired.

