\label{thm:arb}
Let $X^{+}, X^{-}\subset R\mathbb{B}_{2}^{d}$ be any two $\delta$-separated sets and $k$ as defined in \eqref{eq:k}. For any parameter $\gamma\in [0, \max(\delta^2/8Rd, \delta^2/18R\sqrt{k})]$, let $N$ be the $(\delta, 8R^2/\gamma )$-mutual complexity of $X^+$ and $X^-$. Let centers $C^{+}$ and $C^{-}$ be as guaranteed by \cref{def:complexity}. Recall $\mathcal{M}$ from \eqref{eq:p}. We have
\begin{enumerate}
    \item[(i)] $C^+$ and $C^-$ with parameter $\gamma$ satisfy the input conditions of \cref{alg:det_onelayer}.
    \item[(ii)] Let $\Phi$ be the output of \cref{alg:det_onelayer} on $C^+$ and $C^-$ with parameter $\gamma$. Then, $\Phi(X^+)$ and $\Phi(X^-)$ are linearly separable with margin at least $\sqrt{N}\mathcal{M}(\gamma/2, N)$.
\end{enumerate}

	Applying \cref{def:complexity} to that sets $X^+$ and $X^-$ have $(\delta, 8R^2/\gamma)$-mutual complexity $N$. Since $C^+, C^-\subset R\mathbb{B}_2^d$ are $\delta$-separated, for any center $c_i^\pm$
\[ \delta\leq \mathrm{dist} \left(c_{i}^\pm, C^{\mp}\right)\leq 2R.\] 
Then, for any radius $r_i^\pm$, we have that
\begin{equation}\label{eq:ri}
r_i^\pm \leq \frac{\gamma}{8R^2}\mathrm{dist} \left(c_{i}^\pm, C^{\mp}\right)^2 \leq \frac{\gamma}{8R^2} (2R)^2=\frac{\gamma}{2}.
\end{equation}
We re-order the points in $C^+\cup C^-$ as in \cref{alg:det_onelayer}, i.e., for every $i$, let $c_i$ be the point in $C^+\cup C^-$ with the $i$-th largest norm. Similarly, let $r_i$ now be the radius associated to $c_i$. Hence, \eqref{eq:ri} implies $r_i\leq \gamma/2$ for all $i$. Also, let $\sigma (c_i)=+1$ if $c_i\in C^+$ and $\sigma (c_i)=-1$ if $c_i\in C^-$ as in \eqref{eq:sigma}. Therefore, the first condition of \cref{def:complexity} says that $c_i\in \mathrm{conv}(X_i)$ where $X_i:=X^{\sigma(c_i)}\cap \mathbb{B}_2^d(c_i, r_i)$.

\paragraph{Proof of Part (i)}
Here we show that if the input conditions of \cref{alg:det_onelayer} are satisfied for $X^{+}$ and $X^{-}$, then those must be satisfied for the sets $C^{+}$ and $C^{-}$. For convenience, let $k_X$ be $k$ in \eqref{eq:k} for $X^+$ and $X^-$ and let $k_C$ be $k$ in \eqref{eq:k} where we replace $X^+$ and $X^-$ by $C^+$ and $C^-$. We check the following:
\begin{itemize}
    \item The dimension $d$ doesn't change since $C^+, C^-\subset \mathbb{R}^d$, so $d$ is preserved.
    \item By \cref{def:complexity}, $C^+$ and $C^-$ are $\delta$-separated finite sets, so $\delta$ is preserved.
    \item By \cref{def:complexity}, $X_i\neq\emptyset$ and $c_i\in \mathrm{conv}(X_i)$ for every $i$. Hence, \cref{lem:geo lm}(2) implies $\Vert c_i\Vert \leq \Vert x\Vert \leq R$ for some $x\in X_i$. Thus, $C^+, C^-\subset R\mathbb{B}_2^d$, which means $R$ is preserved.
\end{itemize}
Finally, we check $\gamma$ satisfies the input condition now on $C^+$ and $C^-$ if it satisfies that for $X^+$ and $X^-$. Since $c_i\in \mathrm{conv}(X_i)$ for every $i$, \cref{lem:geo lm}(2) implies for every vector $g$ and indices $i$ with $\sigma(c_i)=+1$ and $\sigma (c_j)=-1$, there exists $x_i\in X_i$ and $x_j\in X_j$ such that $g^{\intercal}x_i\geq g^{\intercal}c_i$ and $(-g)^{\intercal}x_j\geq (-g)^{\intercal}c_j$. Hence
\[     w(C^+)
 = \mathbb{E}  \sup\lbrace g^{\intercal}(c_i) :\sigma(c_i)=+1\rbrace 
\leq \mathbb{E}  \sup\lbrace g^{\intercal}(x_i)\rbrace 
\leq \mathbb{E}  \sup\lbrace g^{\intercal}x : x\in X^+ \rbrace 
= w(X^+)\]
and similarly $w(C^-)\leq w(X^-)$, where with expectation is taken over $g$. Now
\begin{align*}
    w(C^+-C^-) & = \mathbb{E}  \sup \lbrace g^{\intercal}c : {c\in C^+-C^-}\rbrace 
    \\ & = \mathbb{E}  \sup\lbrace g^{\intercal}(c_i-c_j) :\sigma(c_i)=+1, \sigma (c_j)=-1 \rbrace
    \\ & \leq \mathbb{E}  \sup\lbrace g^{\intercal}(x_i-x_j) : x_i \in X_i, x_j \in X_j\rbrace 
    \\ & \leq \mathbb{E}  \sup\lbrace g^{\intercal}x : x\in X^+-X^- \rbrace 
    \\ & = w(X^+-X^-).
\end{align*}
Since we showed $R, \delta, d$ are preserved, this implies $k_X\geq k_C$, we obtain that
\[\gamma \leq \max(\delta^2/8Rd, \delta^2/18R\sqrt{k_X})\leq \max(\delta^2/8Rd, \delta^2/18R\sqrt{k_C}).\]
Thus, as $\gamma$ satisfies its input condition for $X^+$ and $X^-$, it does for $C^+$ and $C^-$.

\paragraph{Proof of Part (ii)}
Here we show that the output of \cref{alg:det_onelayer} on $C^{+}$ and $C^{-}$ linearly separates the points from $X^{+}$ and $X^{-1}$ with a margin $\sqrt{N}\mathcal{M}(\gamma/2, N)$. By Part (i), we can run \cref{alg:det_onelayer} on $C^+$ and $C^-$ with parameter $\gamma$ to define $h_j$ for each $1\leq j\leq N$ as in line 6. Let * denote unimportant reals. By definition of $h_j$, we obtain the exact same statement as \eqref{eq:hj} but for $C^+$ and $C^-$, i.e.
\begin{equation}\label{eq:hjci}
h_{j}(c_{i})=\begin{cases}
\leq -\gamma & \textup{if $j<i$ and $\sigma(c_j) \neq \sigma(c_i) $}\\
\geq \gamma  & \textup{if $j=i$}\\
* & \textup{otherwise}
\end{cases}.
\end{equation}
As $r_i\leq \gamma/2$ by \eqref{eq:ri}, for every $i, j$ and $x_{i}\in \mathbb{B}_2^d(c_{i}, r_{i})$, we have 
\[ 
    \vert h_{j}(x_{i})-h_{j}(c_{i})\vert =\vert w_{j}^{\intercal}(x_{i}-c_{i})\vert\leq \Vert x_{i}-c_{i}\Vert\leq r_{i}\leq \frac{\gamma}{2}.
\]
This gives an analog of \eqref{eq:hjci} on the entire sets $X_i$, i.e. for every $x_i\in X_i$
\begin{equation}\label{eq:hjxi}
h_{j}(x_{i})=\begin{cases}
\leq -\gamma/2 & \textup{if $j<i$ and $\sigma(x_j) \neq \sigma(x_i) $}\\
\geq \gamma/2  & \textup{if $j=i$}\\
* & \textup{otherwise}
\end{cases}.
\end{equation}
Hence, after activation, for every $x_i\in X_i$
\begin{equation}\label{eq:phi}
(\Phi(x_i))_j=\mathrm{ReLU}(h_{j}(x_{i}))=\begin{cases}
0  & \textup{if $j<i$ and $\sigma(x_j) \neq \sigma(x_i) $}\\
\geq \gamma/2  & \textup{if $j=i$}\\
\geq 0 & \textup{otherwise}
\end{cases}.
\end{equation}

We now proceed exactly as the proof of \cref{thm:arb}, except since $x_i$ can be any point in cluster $X_i$, we use supremum over $X_i$ instead of just $x_i$. Then, the proof will show the clusters $X_i$ are linearly separable according to $\sigma(x_i)$, which suffices since the clusters partition $X^+\cup X^-$. We choose the weight vector $a\in\mathbb{R}^N$ by picking $a_{i}$ recursively for $i=N, N-1, \dots , 1$ as follows:
\[ a_{i}=\frac{2\sigma(c_i) }{\gamma }\sup_{x\in X_i}\left(1+\left|\sum_{j=i+1}^{N}a_{j}(\Phi(x_{i}))_{j}\right|\right)\]
and so for hyperplane o$H(z)=a^{\intercal}z$, every $x_i\in X_i$, and every $i\in [N]$,
\begin{align*}
\sigma(x_i)  H(\Phi(x_{i})) & = \sigma(x_i) \sum_{j=1}^{N}a_{j}(\Phi(x_{i}))_{j}
\\ & = \sigma(x_i) \sum_{j<i, \sigma(x_j) =\sigma(x_i) }a_{j}(\Phi(x_{i}))_{j} + \sigma(x_i) \sum_{j<i, \sigma(x_j) \neq \sigma(x_i) }a_{j}(\Phi(x_{i}))_{j}
\\ & \qquad + \sigma(x_i) a_{i}(\Phi(x_{i}))_{i} + \sigma(x_i) \sum_{j>i}a_{j}(\Phi(x_{i}))_{j}
\end{align*}
by breaking into four cases similar to the proof of \cref{thm:fin}. The first term is non-negative since $a_j$ has the same sign as $\sigma(x_j)=\sigma(x_i)$ and coordinates of $\Phi(x_i)$ are non-negative due to $\mathrm{ReLU}$-activation. The second term is zero since $(\Phi(x_i))_j=0$ for such $j$ by \eqref{eq:phi}. Hence
\begin{align*}
\sigma(x_i)  H(\Phi(x_{i})) & \geq 0 + 0 + \frac{2\sigma(x_i) ^{2}}{\gamma}\sup_{x\in X_i}\left(1+\left|\sum_{j>i}a_{j}(\Phi(x_{i}))_{j}\right|\right)\left(\frac{\gamma}{2}\right)+\sigma(x_i) \sum_{j>i}a_{j}(\Phi(x_{i}))_{j}
\\ & = \sup_{x\in X_i}\left( 1+\left|\sum_{j>i}a_{j}(\Phi(x_{i}))_{j}\right|\right)+\sigma(x_i) \sum_{j>i}a_{j}(\Phi(x_{i}))_{j}
\\ & \geq 1
\end{align*}
by the triangle inequality. Thus, $H (\Phi(x_{i}))\geq 1$ if $x_{i}\in X^{+}$ and $H (\Phi(x_{i}))\leq -1$  if $x_{i}\in X^{-}$, so $H(z)=a^{\intercal}z$ separates $\Phi (X^{+})$ and $\Phi (X^{-})$. The margin of separation is at least $1/\Vert a\Vert$. We bound this as follows. Exactly as \eqref{eq:hiy}, $\vert h_{i}(y)\vert \leq 2R$ for every $y\in R\mathbb{B}_2^d$. Now, we bound each weight $a_{i}$
\[
\vert a_{i}\vert = \frac{2}{\gamma }\sup_{x\in X_i}\left( 1+\left|\sum_{j=i+1}^{N}a_{j}(\Phi(x_{i}))_{j}\right|\right)
\leq \frac{2}{\gamma} \left(1+2R \sum_{j=i+1}^{N}\vert a_{j}\vert\right).
\]




Thus, $\vert a_{i}\vert \leq \tilde{a}_{i}$ where $\tilde{a}_{i}$ is defined recursively by $\tilde{a}_{N}= 2/\gamma = \vert a_{N}\vert$ and 
\[
    \tilde{a}_{i} = \frac{2}{\gamma}\left(1 + 2R \sum_{j=i+1}^N \tilde{a}_j\right).
\]
We compute $\tilde{a}_{i}$ explicitly. Taking the successive differences
\[
    \tilde{a}_{i-1}-\tilde{a}_{i} = \frac{2}{\gamma}\left(1 + 2R \sum_{j=i}^N \tilde{a}_j\right) - \frac{2}{\gamma}\left(1 + 2R \sum_{j=i+1}^N \tilde{a}_j\right) = \left(\frac{4R}{\gamma}\right)\tilde{a}_{i},
\]




and using the fact that $\tilde{a}_{N}= 2/\gamma$, we get
\[
    \tilde{a}_{i} = \frac{2}{\gamma}\left(1+\frac{4R}{\gamma}\right)^{N-i}.
\]
Hence,
\[
\Vert a\Vert ^{2} \leq \sum_{i=1}^{N}\frac{4}{\gamma^{2}}\left(1+\frac{4R}{\gamma}\right)^{2(N-i)} = \frac{4}{\gamma^{2}} \cdot \frac{(1+4R/\gamma)^{2N}-1}{(1+4R/\gamma )^{2}-1} = \frac{(1+2R/(\gamma/2))^{2N}-1}{4R(R+\gamma/2)}.
\]
Rearranging gives desired bound on the margin: $1/\Vert a\Vert\ge \sqrt{N}\mathcal{M}(\gamma/2, N)$.

